pub fn is_palindrome(s: &str) -> bool {
    let mut chars: Vec<char> = s.chars().map(|c| c.to_ascii_lowercase()).collect();
    let mut i = 0;
    let mut j = chars.len() - 1;
    while i < j {
        if !chars[i].is_alphanumeric() || !chars[j].is_alphanumeric() {
            i += 1;
            continue;
        }
        if chars[i] != chars[j] {
            return false;
        }
        i += 1;
        j -= 1;
    }
    true
}

