    let mut left = 0;
    let mut right = v.len() - 1;
    while left <= right {
        let mid = left + (right - left) / 2;
        if v[mid] == target {
            return Some(mid);
        } else if v[mid] < target {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    None
}

