    let mut stack: VecDeque<char> = VecDeque::new();
    for c in s.chars() {
        match c {
            '(' | '[' | '{' => stack.push_back(c),
            ')' | ']' | '}' => {
                if stack.pop_back().is_none() {
                    return false;
                }
            }
            _ => {}
        }
    }
    stack.is_empty()
}

