pub fn hex_to_rgb(s: &str) -> Option<(u8, u8, u8)> {
    if s.len() != 6 {
        return None;
    }
    let (r, g, b) = s.chars()
        .skip(1)
        .take(3)
        .map(|c| c.to_digit(16).map(|x| x as u8))
        .collect::<Result<Vec<u8>, _>>()
        .map(|v| v.into_iter().map(|x| x * 16).collect::<Vec<u8>>());
    if r.is_none() || g.is_none() || b.is_none() {
        return None;
    }
    Some((r.unwrap(), g.unwrap(), b.unwrap()))
}

